import React, { useState } from "react";
import "./ScheduleTable.css";

const ScheduleTable = ({ schedule, title, showSala = true, editable = false, onDataChange }) => {
  const [scheduleData, setScheduleData] = useState(schedule || []); // Inițializează cu un array gol
  const [showPopup, setShowPopup] = useState(false);
  const [selectedEntry, setSelectedEntry] = useState(null);
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({});

  const handleEditClick = (entry) => {
    setSelectedEntry(entry);
    setFormData(entry);
    setShowPopup(true);
    setIsEditing(false);
  };

  const closePopup = () => {
    setShowPopup(false);
    setSelectedEntry(null);
    setIsEditing(false);
  };

  const handleAddNew = () => {
    const newEntry = {
      id: null,
      zi: "Luni",
      interval: "08:00 - 10:00",
      disciplina: "Nouă Disciplina",
      tip: "Curs",
      grupa: "A1",
      sala: "C101",
      profesor: "Profesor Nou",
      an: 1,
    };

    setSelectedEntry(newEntry);
    setFormData(newEntry);
    setShowPopup(true);
    setIsEditing(true);
  };

  return (
    <div className="schedule-table-container">
      <h2>{title}</h2>
      <table className="schedule-table">
        <thead>
          <tr>
            <th>Zi</th>
            <th>Interval</th>
            <th>Disciplina</th>
            <th>Tip</th>
            <th>Grupa</th>
            {showSala && <th>Sală</th>}
            <th>Profesor</th>
            <th>An</th>
            {editable && <th>Acțiuni</th>}
          </tr>
        </thead>
        <tbody>
          {Array.isArray(scheduleData) && scheduleData.length === 0 ? (
            <tr>
              <td colSpan={showSala ? (editable ? 9 : 8) : (editable ? 8 : 7)} style={{ textAlign: "center" }}>
                Nu există date disponibile pentru afișare.
              </td>
            </tr>
          ) : (
            Array.isArray(scheduleData) &&
            scheduleData.map((entry, index) => (
              <tr key={index}>
                <td>{entry.zi || "-"}</td>
                <td>{entry.interval || "-"}</td>
                <td>{entry.disciplina || "-"}</td>
                <td>{entry.tip || "-"}</td>
                <td>{entry.grupa || "-"}</td>
                {showSala && <td>{entry.sala || "-"}</td>}
                <td>{entry.profesor || "-"}</td>
                <td>{entry.an || "-"}</td>
                {editable && (
                  <td>
                    <button
                      className="edit-button"
                      onClick={() => handleEditClick(entry)}
                    >
                      ✏️ Editare
                    </button>
                  </td>
                )}
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
};

export default ScheduleTable;
